\item \S\ref{sec:balanced}: balanced key laws, the modal fraction law, the
  two-sided pin at $w=b/2$, and law-change capacity.
\end{itemize}

\section{Preliminaries: tie profiles and the tie ceiling}

\begin{definition}[tie profile]
Let $S$ be an integer-valued statistic on a finite sample of size $n$. The
\emph{tie profile} of $S$ is the multiset $L=[m_1,\dots,m_r]$ of cardinalities
of the level sets of $S$, so $\sum_i m_i=n$. We write $L.\mathrm{sum}=n$.
\end{definition}

\begin{definition}[Kendall tie correction]
For a tie profile $L$, $\;\Tie(L)=\tfrac1{12}\sum_i(m_i^3-m_i)$.
\end{definition}

\begin{definition}[tie ceiling]
For $L$ with $n=L.\mathrm{sum}\ge2$,
\[
\rho^2(L)=1-\frac{12\,\Tie(L)}{n^3-n}=1-\frac{\sum_i(m_i^3-m_i)}{n^3-n},
\qquad \rho(L)=\sqrt{\rho^2(L)}.
\]
\end{definition}

\begin{proposition}[interpretation]\label{prop:interp}
$\rho(L)$ is the maximum Spearman rank correlation attainable between a
statistic with tie profile $L$ and any untied response.
\end{proposition}

\begin{proof}[Proof sketch]
Spearman's $\rho$ is the Pearson correlation of midranks. If $R$ is an untied
ranking then $\Var(R)=(n^3-n)/12$, while replacing each tied block of size $m$
by its common midrank removes exactly $(m^3-m)/12$ of that variance, so
$\Var(\bar R)=\bigl(n^3-n-\sum_i(m_i^3-m_i)\bigr)/12$. Since $\bar R$ is a
coarsening of $R$, the correlation is bounded by the ratio of standard
deviations, with equality when the response is monotone in the statistic and
untied within blocks.
\end{proof}

Two elementary consequences used throughout: $\rho^2(L)\in[0,1]$, and
$\rho^2([n])=0$.

\begin{example}\label{ex:151}
$\rho^2([15,1])=1-\frac{3360}{4080}=\frac3{17}\approx0.1765$, so
$\rho\approx0.4201$.
\end{example}

\begin{definition}[capped profile]
For $0\le u\le b$ let
$C(u,b)=\bigl[2^{b-1},2^{b-2},\dots,2^{b-u},2^{b-u}\bigr]$, a list of $u+1$
entries when $u\ge1$, and $C(0,b)=[2^b]$.
\end{definition}

\begin{proposition}[arithmetic bridge]\label{prop:bridge}
For $u\le b$, $C(u,b)$ is exactly the tie profile of $T_u$ on
$\{0,\dots,2^b-1\}$: for $0\le k<u$ the set $\{x<2^b:v_2(x)=k\}$ has $2^{b-1-k}$
elements, and the top class $\{x<2^b:2^u\mid x\}$ has $2^{b-u}$ elements.
\end{proposition}

\begin{proof}[Proof sketch]
The multiples of $2^k$ below $2^b$ number $2^{b-k}$; subtracting the multiples
of $2^{k+1}$ leaves $2^{b-1-k}$ of exact valuation $k$. The top class is the
multiples of $2^u$. The convention for $v_2(0)$ is immaterial: $0$ lies in the
top class either way.
\end{proof}

\begin{proposition}\label{prop:sum}
For $u\le b$, $\sum C(u,b)=2^b$.
\end{proposition}

\begin{proof}[Proof sketch]
Induction on $u$, using $C(u+1,b+1)=2^b\!::\!C(u,b)$ and $2^b+2^b=2^{b+1}$.
\end{proof}

At $u=b$ the profile is the full dyadic one $[2^{b-1},\dots,2,1,1]$.

\section{The separation law and the rank-one ceiling table}\label{sec:sep}

\begin{theorem}[Kendall correction of the capped profile]\label{thm:tiecorr}
For $u,r\ge0$ and $b=u+r$,
\[
12\,\Tie\bigl(C(u,b)\bigr)=\frac{8^{b}+6\cdot8^{\,b-u}}{7}-2^{b}.
\]
\end{theorem}

\begin{proof}[Proof sketch]
Induction on $u$. For $u=0$ the profile is $[2^b]$, with correction $8^b-2^b$.
The step prepends a block of size $2^{b}$, contributing $8^{b}-2^{b}$; the
geometric bookkeeping $8^{b+1}=8\cdot8^b$, $2^{b+1}=2\cdot2^b$ closes the
recursion.
\end{proof}

\begin{theorem}[Separation law]\label{thm:sep}
For $1\le b$ and $u\le b$,
\[
\rho^2(b,u):=\rho^2\bigl(C(u,b)\bigr)
=\frac67\Bigl(1-\Bigl(\tfrac18\Bigr)^{u}\Bigr)\Bigl(1+\frac1{4^{b}-1}\Bigr).
\]
\end{theorem}

\begin{proof}[Proof sketch]
Put $n=2^b$, so $n^3=8^b$, $n^2=4^b$. By Theorem~\ref{thm:tiecorr},
\[
\rho^2=1-\frac{\frac{8^b+6\cdot8^{b-u}}{7}-2^b}{8^b-2^b}
=\frac{\frac67\bigl(8^b-8^{b-u}\bigr)}{8^b-2^b}
=\frac67\cdot\frac{1-8^{-u}}{1-4^{-b}},
\]
and $\frac1{1-4^{-b}}=1+\frac1{4^b-1}$.
\end{proof}

Write $\capf(u)=\tfrac67(1-8^{-u})$ and $\bitf(b)=1+\tfrac1{4^b-1}$, so that
$\rho^2(b,u)=\capf(u)\bitf(b)$ with $0<\capf(u)\le6/7$ for $u\ge1$ and
$\bitf(b)>1$ for $b\ge1$.

\begin{corollary}[consistency at full cap]
At $u=b$ the formula reduces to the uncapped dyadic ceiling
$\tfrac67(1-8^{-b})(1+\tfrac1{4^b-1})$, which tends to $6/7$ from above; hence
$\rho\to\sqrt{6/7}=0.925820\ldots$
\end{corollary}

\begin{theorem}[Rank-one law]\label{thm:rankone}
For all $b,b'\ge1$ and $u\le b$, $u'\le b'$,
\[
\rho^2(b,u)\,\rho^2(b',u')=\rho^2(b,u')\,\rho^2(b',u).
\]
\end{theorem}

\begin{proof}[Proof sketch]
Both sides equal $\capf(u)\capf(u')\bitf(b)\bitf(b')$ by Theorem~\ref{thm:sep}.
\end{proof}

A matrix all of whose $2\times2$ minors vanish has rank one, i.e.\ is an outer
product. Every row of the ceiling table is a scalar multiple of every other row,
and likewise for columns: there is no cell-specific term in which a cliff could
reside. This is the precise sense in which the instrument admits no cliff.

\begin{theorem}[strict monotonicity in the cap]\label{thm:monou}
If $u<u'\le b$ and $b\ge1$ then $\rho^2(b,u)<\rho^2(b,u')$.
\end{theorem}

\begin{theorem}[strict antitonicity in the bit length]\label{thm:antib}
If $1\le u$, $b<b'$ and $u\le b$ then $\rho^2(b',u)<\rho^2(b,u)$.
\end{theorem}

\begin{proof}[Proof sketch of Theorems~\ref{thm:monou}--\ref{thm:antib}]
$\capf$ is strictly increasing and positive for $u\ge1$; $\bitf$ is strictly
decreasing and positive.
\end{proof}

\begin{theorem}[uniform bit-length insensitivity]\label{thm:insens}
For $1\le b\le b'$ and $u\le b$,
$\;0\le\rho^2(b,u)-\rho^2(b',u)<2\cdot4^{-b}$, uniformly in $u$.
\end{theorem}

\begin{proof}[Proof sketch]
The difference is $\capf(u)\bigl(\bitf(b)-\bitf(b')\bigr)\le
\tfrac67\bigl(\tfrac1{4^b-1}-\tfrac1{4^{b'}-1}\bigr)<\tfrac67\cdot\tfrac1{4^b-1}<2\cdot4^{-b}$.
\end{proof}

