\section{Floor laws: why no cell can break down}\label{sec:floor}

\begin{theorem}[Mass-fraction floor law]\label{thm:massfloor}
Let $L$ be a tie profile with $n=L.\mathrm{sum}\ge2$ and let $0\le a<1$ satisfy
$m_i\le a\,n$ for every block. Then $\rho^2(L)>1-a^2$.
\end{theorem}

\begin{proof}[Proof sketch]
From $0\le m_i\le an$ we get $m_i^3\le(an)^2m_i$, hence
$\sum_i m_i^3\le a^2n^2\sum_i m_i=a^2n^3$ and
\[
\frac{\sum_i(m_i^3-m_i)}{n^3-n}\le\frac{a^2n^3-n}{n^3-n}<a^2,
\]
the last step because $a^2n<n$. Subtract from $1$.
\end{proof}

The proof uses neither the number of blocks, nor their arithmetic origin, nor
the underlying probability law: only the modal mass.

\begin{definition}[balanced statistic]
A tie profile $L$ is \emph{balanced} if $2m_i\le L.\mathrm{sum}$ for every block,
i.e.\ no value carries a strict majority.
\end{definition}

\begin{theorem}[Distribution-free floor law]\label{thm:balfloor}
If $L$ is balanced with $L.\mathrm{sum}\ge2$ then
$\rho^2(L)>\tfrac34$, hence $\rho(L)>0.866>0.53$.
\end{theorem}

\begin{proof}[Proof sketch]
Theorem~\ref{thm:massfloor} with $a=1/2$.
\end{proof}

\begin{proposition}[every cell is balanced]\label{prop:cellbal}
For $1\le u\le b$ the profile $C(u,b)$ is balanced: its largest block is
$2^{b-1}=\tfrac12\sum C(u,b)$.
\end{proposition}

\begin{corollary}[universal cell floor]\label{cor:cellfloor}
For every $1\le u\le b$, $\rho(b,u)>0.866>0.53$. Every cell of the recorded
envelope clears the recorded floor with margin at least $0.33$; a reading below
$0.53$ can never be attributed to tie granularity.
\end{corollary}

\begin{theorem}[Cliff edge]\label{thm:cliffedge}
If every block satisfies $m_i\le a\,n$ with $0\le a\le0.847$ and $n\ge2$, then
$\rho(L)>0.53$.
\end{theorem}

\begin{proof}[Proof sketch]
Theorem~\ref{thm:massfloor} gives $\rho^2>1-0.847^2=0.282591>0.2809=0.53^2$.
\end{proof}

\begin{theorem}[Sharpness]\label{thm:sharp}
The profile $[15,1]$, whose modal class carries $93.75\%$ of the sample, has
$\rho^2=3/17\approx0.1765$ and $\rho\approx0.4201<0.53$. Hence the balance
hypothesis of Theorem~\ref{thm:balfloor} cannot be dropped.
\end{theorem}

\begin{proof}[Proof sketch]
Example~\ref{ex:151}.
\end{proof}

Theorems~\ref{thm:cliffedge} and~\ref{thm:sharp} localise the failure of the
$0.53$ floor to modal mass $a\in[0.848,0.938]$, tightened to $a\in[0.848,0.8955]$
by Proposition~\ref{prop:bracket} below. The tested envelope has modal
mass exactly $1/2$ everywhere.

\begin{proposition}[sharpening the bracket]\label{prop:bracket}
For the two-block family $[\lfloor an\rfloor,\,n-\lfloor an\rfloor]$ one has
\[
\rho^2=1-\frac{(an)^3+((1-a)n)^3-n}{n^3-n}\;\xrightarrow[n\to\infty]{}\;3a(1-a),
\]
which crosses $0.53^2=0.2809$ at
$a=\tfrac12\bigl(1+\sqrt{1-4\cdot0.2809/3}\bigr)=0.89543\ldots$; explicitly,
$[8955,1045]$ has $\rho^2=0.280739\ldots<0.2809$. Hence the critical modal mass
lies in $[0.848,0.8955]$.
\end{proposition}

\begin{remark}[the exact constant]
For fixed modal mass and fixed $n$, splitting the non-modal mass into further
classes only raises the ceiling (Theorem~\ref{thm:coarse}), so two-block
profiles are the worst case and $0.89543\ldots$ should be the exact critical
constant; making this uniform in $n$ is the remaining step.
\end{remark}

\section{Coarsening, and how much resolution can be worth}\label{sec:gap}

\begin{lemma}[additivity]
$\Tie(X\mathbin{+\!\!+}Y)=\Tie(X)+\Tie(Y)$.
\end{lemma}

\begin{lemma}[merging increases the correction]\label{lem:merge}
For $m,m'\ge0$, $\;(m^3-m)+(m'^3-m')\le(m+m')^3-(m+m')$, with strict inequality
unless $mm'=0$; the difference is $3mm'(m+m')$.
\end{lemma}

\begin{theorem}[Coarsening law]\label{thm:coarse}
Let $L=A\mathbin{+\!\!+}[m,m']\mathbin{+\!\!+}B$ and let
$L'=A\mathbin{+\!\!+}[m+m']\mathbin{+\!\!+}B$. Then $L$ and $L'$ have the same sum
and $\rho^2(L')\le\rho^2(L)$: merging tie classes never raises the ceiling.
\end{theorem}

\begin{proof}[Proof sketch]
Equal sums; larger correction by Lemma~\ref{lem:merge}; the ceiling is a
decreasing affine function of the correction at fixed $n$.
\end{proof}

\begin{theorem}[lowering the cap is a merge]\label{thm:capmerge}
For $u,r\ge0$ and $b=u+1+r$, the profile $C(u,b)$ is obtained from $C(u+1,b)$
by merging its last two classes, both of size $2^{r}$. Consequently
$\rho^2\bigl(C(u,b)\bigr)\le\rho^2\bigl(C(u+1,b)\bigr)$.
\end{theorem}

This re-derives Theorem~\ref{thm:monou} without the closed form and explains
\emph{why} the finer dial dominates: coarsening a partition is a cubic-loss
operation.

Write $G_{\rho^2}(b,u)=\rho^2(b,u)-\rho^2(b,1)$ and
$G_{\rho}(b,u)=\rho(b,u)-\rho(b,1)$.

\begin{theorem}[Gap law, lower half]\label{thm:gaplow}
For $2\le u\le b$, $\;G_{\rho^2}(b,u)\ge\tfrac3{32}=0.09375$.
\end{theorem}

\begin{proof}[Proof sketch]
$\capf(u)-\capf(1)=\tfrac67(8^{-1}-8^{-u})\ge\tfrac67\cdot\tfrac7{64}=\tfrac3{32}$
and $\bitf(b)\ge1$.
\end{proof}

\begin{theorem}[Gap law, upper half]\label{thm:gaphigh}
For $1\le u\le b$, $\;G_{\rho}(b,u)<0.07$, with supremum over the envelope equal
to $\sqrt{6/7}-\sqrt{3/4}=0.925820\ldots-0.866025\ldots=0.059795\ldots$
\end{theorem}

\begin{proof}[Proof sketch]
Set $X=\rho^2(b,u)$ and $Y=\rho^2(b,1)\ge3/4$. It suffices that
$X<(\sqrt Y+0.07)^2=Y+0.14\sqrt Y+0.0049$; since $\sqrt Y\ge0.866$ this holds as
soon as $X-Y\le\tfrac67\bitf(b)-\tfrac34<0.1213$, which follows from
Theorem~\ref{thm:sep}. The degenerate cell $b=u=1$ has gap $0$.
\end{proof}

The apparent mismatch between Theorems~\ref{thm:gaplow} and~\ref{thm:gaphigh} is
a consequence of working near the top of the range, where the square root
compresses differences by $\approx1/(2\rho)\approx0.56$: $0.09375$ in $\rho^2$
is worth about $0.052$ in $\rho$.

\begin{theorem}[Recorded advantage forces slack]\label{thm:slack}
Suppose at a cell $1\le u\le b$ the capped dial reads $r_T\le\rho(b,u)$ and the
bare count reads $r_C$ with $r_T-r_C\ge0.10$. Then
$\;\rho(b,1)-r_C\ge0.03$.
\end{theorem}

\begin{proof}[Proof sketch]
$\rho(b,1)-r_C=(\rho(b,1)-\rho(b,u))+(\rho(b,u)-r_T)+(r_T-r_C)>-0.07+0+0.10$.
\end{proof}

Thus the recorded advantage band $[0.10,0.15]$ lies strictly above the
tie-resolution capacity of the family at every cell: the superiority of $T_u$
over parity is not a granularity artefact, and parity must be leaving at least
$0.03$ of its own available correlation on the table --- information carried by
the deeper valuations $v_2\ge2$.

\section{Balanced key laws: fixed Hamming weight}\label{sec:balanced}

\begin{definition}
For $1\le w\le b$ set
$W(b,w)=\bigl[\binom{b-1-k}{w-1}\bigr]_{k=0}^{\,b-w}$.
\end{definition}

\begin{theorem}[combinatorial bridge]
$W(b,w)$ is the tie profile of the trailing-zero statistic on weight-$w$ $b$-bit
keys: modelling such a key as a $w$-subset $S\subseteq\{0,\dots,b-1\}$ of
set-bit positions, the number of $S$ with $\min S=k$ is $\binom{b-1-k}{w-1}$.
\end{theorem}

\begin{theorem}[hockey-stick normalisation]
For $1\le w\le b$, $\;\sum_{k=0}^{b-w}\binom{b-1-k}{w-1}=\binom{b}{w}$.
\end{theorem}

\begin{proof}[Proof sketch]
Reindex $j=b-w-k$ to get $\sum_{j=0}^{b-w}\binom{w-1+j}{w-1}$ and apply the
hockey-stick identity.
\end{proof}

\begin{theorem}[Modal fraction law]\label{thm:modal}
For $1\le w\le b$, $\;b\binom{b-1}{w-1}=w\binom{b}{w}$: the modal tie class is
the class of odd keys and carries exactly the fraction $w/b$ of them.
\end{theorem}

\begin{theorem}[Balance transfer]\label{thm:transfer}
If $1\le w$ and $2w\le b$ then $W(b,w)$ is balanced.
\end{theorem}

\begin{proof}[Proof sketch]
The largest block is $\binom{b-1}{w-1}$ and by Theorem~\ref{thm:modal}
$b\cdot2\binom{b-1}{w-1}=2w\binom bw\le b\binom bw$; divide by $b>0$.
\end{proof}

\begin{corollary}[Balanced floor]
For $1\le w$ with $2w\le b$,
$\rho^2\bigl(W(b,w)\bigr)>\tfrac34$ and $\rho\bigl(W(b,w)\bigr)>0.866>0.53$.
\end{corollary}

Key balance in the Hamming sense implies tie balance in the statistical sense;
that is the whole mechanism.

\begin{theorem}[exact half at the balanced weight]
For $v\ge1$, $\;2\binom{2v-1}{v-1}=\binom{2v}{v}$: at $w=b/2$ the modal class is
exactly half the sample.
\end{theorem}

\begin{theorem}[Two-sided pin]\label{thm:pin}
For $v\ge1$ and $n=\binom{2v}{v}=\sum W(2v,v)$,
\[
\tfrac34<\rho^2\bigl(W(2v,v)\bigr)\le\tfrac78+\frac{7}{8(n^2-1)}.
\]
\end{theorem}

\begin{proof}[Proof sketch]
The lower bound is the balanced floor. For the upper bound, a single block of
size $m\ge n/2$ contributes at least $n^3/8-n/2$ to $\sum_i(m_i^3-m_i)$, giving
$\rho^2\le\tfrac78+\tfrac3{8(n^2-1)}$, which the stated bound dominates.
\end{proof}

\begin{theorem}[Law-change capacity]\label{thm:lawchange}
For $v\ge2$, i.e.\ bit length $b=2v\ge4$,
\[
\bigl|\rho\bigl(W(2v,v)\bigr)-\rho\bigl(C(2v,2v)\bigr)\bigr|<0.07 .
\]
\end{theorem}

\begin{proof}[Proof sketch]
By Theorem~\ref{thm:pin} the balanced ceiling lies in $(3/4,15/16]$ in $\rho^2$
(using $n\ge4$); by Theorem~\ref{thm:sep} the dyadic ceiling lies in
$(6/7,6/7+1/256]$. Passing to square roots on the common enclosing interval
yields the bound.
\end{proof}

Switching from uniform to balanced keys therefore cannot move the dial's
capacity by more than $0.07$ in $\rho$: a recorded balanced-versus-uniform
difference exceeding $0.07$ is a statement about the response, not about tie
structure.

\section{Algorithms}

\paragraph{A. Exact tie ceiling from a profile.} Given $[m_1,\dots,m_r]$,
compute $n=\sum m_i$ and $S=\sum(m_i^3-m_i)$ and return the exact rational
$1-S/(n^3-n)$. Cost $O(r)$ big-integer operations; a full ceiling table costs
$O(1)$ per cell via Theorem~\ref{thm:sep}.

\paragraph{B. Capped profile construction and census audit.} Build
$C(u,b)=[2^{b-1},\dots,2^{b-u},2^{b-u}]$ directly in $O(u)$, or, for small $b$,
enumerate $x<2^b$ and bucket by $\min(v_2(x),u)$ in $O(2^b)$ to verify
Proposition~\ref{prop:bridge}.

\paragraph{C. Rank-one certification.} Verify $M_{ij}M_{kl}=M_{il}M_{kj}$ for all
$i<k$, $j<l$ in exact arithmetic ($O(p^2q^2)$), or check each row against the
first ($O(pq)$).

\paragraph{D. Modal-mass floor certificate.} Compute $a=\max_i m_i/n$ and return
the certified bound $\sqrt{1-a^2}$, with verdict ``clears $0.53$'' whenever
$a\le0.847$. Cost $O(r)$; no knowledge of the generating law required.

\paragraph{E. Attribution audit.} Given measured $r_T,r_C$ at a cell $(b,u)$,
compute the capacity gap $\rho(b,u)-\rho(b,1)$; if $r_T-r_C$ exceeds it, report
the forced slack $\rho(b,1)-r_C\ge(r_T-r_C)-(\rho(b,u)-\rho(b,1))$. Cost $O(1)$.

\section{Discussion}

\subsection{What robustness should mean}

The empirical verdict was a conjunction of negatives: no cliff, no breakdown, no
convention artefact. Negatives over a finite grid are weak evidence. The
mathematics replaces each with a positive structural statement. \emph{No cliff}
becomes separability (Theorem~\ref{thm:sep}) and hence rank one
(Theorem~\ref{thm:rankone}): there is no cell-specific term in which a cliff
could reside, and the conclusion extends to untested cells for free. \emph{No
breakdown} becomes the distribution-free floor (Theorem~\ref{thm:balfloor}),
stable under changes of law, arithmetic and statistic. \emph{No convention
artefact} becomes the arithmetic bridge (Proposition~\ref{prop:bridge}): the
profile analysed is literally the valuation census, and the only convention in
sight places $0$ in the top class either way.

\subsection{Capacity as an auditing tool}

Because capacity is known exactly, any recorded effect can be compared against
what capacity could manufacture. The recorded floor is far below capacity, so it
says nothing about the instrument; the recorded advantage of the capped dial
over parity is far above what tie resolution can supply, so it must be
substantive. Theorem~\ref{thm:slack} is a constraint a future measurement must
satisfy. This inverts the usual role of a null model: instead of asking whether
an effect could be noise, one asks whether it could be instrument granularity.

\subsection{Scope and limitations}

First, the ceiling bounds the \emph{attainable} correlation, achieved only when
the response is monotone in the statistic and untied within blocks; the theory
constrains, it does not forecast. Second, the separation law is a property of
geometric block structure: non-geometric profiles, such as the binomial ones of
\S\ref{sec:balanced}, need not factorise, and there we obtain only two-sided
bounds. Third, the constant $0.07$ in Theorem~\ref{thm:gaphigh} is a convenient
rational bound; the true supremum $0.0597954\ldots$ would sharpen the slack in
Theorem~\ref{thm:slack} from $0.03$ to $0.0402\ldots$

\subsection{Future work}

\emph{Rank-one as the signature of statistic composition.} The factorisation
arose because the knobs act on disjoint parts of the profile: the cap truncates
the tail, the bit length rescales the space. We conjecture that composing an
independent resolution operation with an independent scaling operation always
yields a rank-one capacity table, and that a rank-two table certifies genuine
interaction. The abstract characterisation of such families is open.

\emph{The exact cliff constant.} The critical modal mass is bracketed into
$[0.848,0.8955]$; along two-block profiles the ceiling tends to $3a(1-a)$,
crossing $0.53^2$ at $a=0.89543\ldots$, which we conjecture to be the exact
critical constant.

\emph{Slack accounting.} Theorem~\ref{thm:slack} says bare parity must lose at
least $0.03$ of non-tie information. We conjecture this is precisely the
response's dependence on the event $v_2\ge2$, isolable by measuring the dial
with the response conditioned on parity.

\section{Conclusion}

For the capped trailing-zero dial on binary key spaces the rank-correlation
capacity is exactly $\rho^2(b,u)=\tfrac67(1-8^{-u})(1+\tfrac1{4^b-1})$, which
factorises over the two design knobs. Hence the capacity table is rank one --- the
exact meaning of ``no cell-specific cliff'' --- capacity varies by less than
$2\cdot4^{-b}$ along the bit-length axis, and it is monotone in each knob for a
structural reason: coarsening a partition costs a cubic term. Beneath the closed
form lies a distribution-free statement: any statistic whose modal class holds no
majority has capacity above $0.866$, degrading gracefully to $\sqrt{1-a^2}$ at
modal mass $a$ and failing only for $a\in[0.848,0.8955]$. Balanced key laws
inherit the bound through $b\binom{b-1}{w-1}=w\binom bw$. Finally, exact capacity
turns measurement into audit: the recorded $0.10$--$0.15$ advantage of the capped
dial over bare parity exceeds the at most $0.0598$ that tie resolution can
supply, so the excess is real and forces the parity reading at least $0.03$
below its own ceiling.

