from fractions import Fraction
from math import sqrt
from typing import Sequence


def tie_correction(profile: Sequence[int]) -> Fraction:
    """Kendall tie correction T(L) = (1/12) * sum_i (m_i^3 - m_i)."""
    return Fraction(sum(m ** 3 - m for m in profile), 12)


def ceiling_sq(profile: Sequence[int]) -> Fraction:
    """Exact tie ceiling rho^2(L) = 1 - sum(m^3 - m) / (n^3 - n).

    This is the largest squared Spearman rank correlation a statistic with the
    given tie profile can attain against any untied response.
    """
    n = sum(profile)
    if n < 2:
        raise ValueError("a tie ceiling needs at least two observations")
    return Fraction(1) - Fraction(sum(m ** 3 - m for m in profile), n ** 3 - n)


def ceiling(profile: Sequence[int]) -> float:
    """Tie ceiling rho(L)."""
    return sqrt(float(ceiling_sq(profile)))


def separation_formula(b: int, u: int) -> Fraction:
    """Closed form for the capped trailing-zero dial: (6/7)(1-8^-u)(1+1/(4^b-1))."""
    if not 1 <= u <= b:
        raise ValueError("require 1 <= u <= b")
    return (Fraction(6, 7) * (Fraction(1) - Fraction(1, 8 ** u))
            * (Fraction(1) + Fraction(1, 4 ** b - 1)))


def cap_blocks(u: int, b: int) -> "list[int]":
    """Tie profile of T_u(x) = min(v2(x), u) on {0, ..., 2^b - 1}."""
    if not 0 <= u <= b:
        raise ValueError("require 0 <= u <= b")
    if u == 0:
        return [2 ** b]
    return [2 ** (b - 1 - k) for k in range(u)] + [2 ** (b - u)]


if __name__ == "__main__":
    for b, u in ((8, 2), (16, 4), (64, 8)):
        assert ceiling_sq(cap_blocks(u, b)) == separation_formula(b, u)
        print(b, u, float(ceiling(cap_blocks(u, b))))

from fractions import Fraction
from typing import List, Sequence, Tuple


def ceiling_sq(profile: Sequence[int]) -> Fraction:
    n = sum(profile)
    return Fraction(1) - Fraction(sum(m ** 3 - m for m in profile), n ** 3 - n)


def cap_blocks(u: int, b: int) -> List[int]:
    return [2 ** (b - 1 - k) for k in range(u)] + [2 ** (b - u)]


def ceiling_table(bs: Sequence[int], us: Sequence[int]) -> List[List[Fraction]]:
    """Exact ceiling table rho^2(b,u) over a bitlen x cap grid."""
    return [[ceiling_sq(cap_blocks(min(u, b), b)) for u in us] for b in bs]


def rank_one_defect(table: Sequence[Sequence[Fraction]]) -> Fraction:
    """Largest absolute 2x2 minor of the table, in exact arithmetic.

    The table has rank one exactly when this is zero, i.e. when the entries
    factor as f(b) * g(u): no interaction between the two knobs.
    """
    worst = Fraction(0)
    p, q = len(table), len(table[0])
    for i in range(p):
        for k in range(i + 1, p):
            for j in range(q):
                for l in range(j + 1, q):
                    minor = table[i][j] * table[k][l] - table[i][l] * table[k][j]
                    worst = max(worst, abs(minor))
    return worst


def factorisation(table: Sequence[Sequence[Fraction]]) -> Tuple[List[Fraction], List[Fraction]]:
    """Recover the outer-product factors of a rank-one table."""
    row0 = list(table[0])
    col_scale = [table[i][0] / table[0][0] for i in range(len(table))]
    return col_scale, row0


if __name__ == "__main__":
    bs, us = [8, 16, 32, 64], [1, 2, 3, 4, 6, 8]
    T = ceiling_table(bs, us)
    print("largest 2x2 minor:", rank_one_defect(T))
    scale, row = factorisation(T)
    print("row multipliers:", [float(s) for s in scale])

from fractions import Fraction
from math import sqrt
from typing import Dict, Sequence


def modal_mass(profile: Sequence[int]) -> Fraction:
    """Fraction of the sample carried by the largest tie class."""
    return Fraction(max(profile), sum(profile))


def floor_certificate(profile: Sequence[int], target: float = 0.53) -> Dict[str, object]:
    """Distribution-free lower bound on the rank-correlation ceiling.

    Uses only the modal mass a: no arithmetic, no bit length, no cap and no
    draw law enter.  Guarantees rho^2 > 1 - a^2, hence rho > sqrt(1 - a^2).
    A balanced profile (a <= 1/2) always certifies rho > 0.866.
    """
    a = modal_mass(profile)
    certified = sqrt(max(0.0, 1.0 - float(a) ** 2))
    return {
        "modal_mass": float(a),
        "balanced": 2 * max(profile) <= sum(profile),
        "certified_rho_lower_bound": certified,
        "clears_target": certified > target,
        "reason": ("balanced: no value holds a majority, so the ceiling exceeds "
                   "sqrt(3/4) = 0.866" if 2 * max(profile) <= sum(profile)
                   else f"modal class holds {float(a):.4f} of the sample"),
    }


def exact_ceiling(profile: Sequence[int]) -> float:
    n = sum(profile)
    return sqrt(float(Fraction(1) - Fraction(sum(m ** 3 - m for m in profile),
                                             n ** 3 - n)))


if __name__ == "__main__":
    for prof in ([128, 64, 32, 32], [15, 1], [8955, 1045], [35, 20, 10, 4, 1]):
        cert = floor_certificate(prof)
        print(prof, cert["certified_rho_lower_bound"], "exact:",
              exact_ceiling(prof), "clears 0.53:", cert["clears_target"])

