function ATTRIBUTION_AUDIT(b, u, r_dial, r_count):
    dial_ceiling  <- sqrt(SEPARATION(b, u))
    count_ceiling <- sqrt(SEPARATION(b, 1))     # bare parity
    capacity <- dial_ceiling - count_ceiling    # <= 0.059795 always
    observed <- r_dial - r_count
    if r_dial > dial_ceiling:
        return IMPOSSIBLE                       # reading exceeds its own ceiling
    if observed <= capacity:
        return EXPLAINED_BY_TIES                # no conclusion about the response
    return FORCED_SLACK(observed - capacity)    # count loses non-tie information
